Variant Order
  Case Pending
  Case OnItsWay(courier As String)
  Case Delivered(courier As String, hora As Integer)
  Case Canceled(reason As String)
EndVariant

Function text <- Describe(order As Order)
  Define text As String <- "";
  Switch order Do
    Order.Pending: text <- "Pending";
    Order.OnItsWay(who): text <- "On its way with " + who;
    Order.Delivered(who, hora): text <- "Delivered by " + who + " at " + toText(hora);
    Order.Canceled(reason): text <- "Canceled: " + reason;
  EndSwitch
EndFunction

Subroutine Advance(order As Order, courier As String, hora As Integer) As Result<Order, String>
  Switch order Do
    Order.Pending: Return Success(Order.OnItsWay(courier));
    Order.OnItsWay(who): Return Success(Order.Delivered(who, hora));
    Order.Delivered(who, when): Return Failure("already delivered by " + who + " at " + toText(when));
    Order.Canceled(reason): Return Failure("it is canceled: " + reason);
  EndSwitch
EndSubroutine

Algorithm Advances
  Define start, reason As String;
  Define times As Integer;
  Read start;
  Define order As Order <- Order.Pending;
  If start = "canceled" Then
    Read reason;
    order <- Order.Canceled(reason);
  EndIf
  Read times;
  Define problem As String <- "";
  For paso <- 1 To times Do
    If problem = "" Then
      Switch Advance(order, "Sol", 14) Do
        Success(next): order <- next;
        Failure(cause): problem <- cause;
      EndSwitch
    EndIf
  EndFor
  If problem = "" Then
    Write Describe(order);
  Else
    Write "Cannot: ", problem;
  EndIf
EndAlgorithm
